@PartitionH3.survivorCoefficient : {n : ℕ} → PartitionH3.NaturalUnitInterval n → ℕ → PartitionH3.Coeff
PartitionH3.elementary_zero : ∀ (m : ℕ), PartitionH3.elementary m 0 = 1
PartitionH3.elementary_isSymmetric : ∀ (m k : ℕ), MvPolynomial.IsSymmetric (PartitionH3.elementary m k)
