@PartitionH3.same_color_comparable : ∀ {n m : ℕ} (H : PartitionH3.NaturalUnitInterval n) (κ : Fin n → Fin m),
  PartitionH3.Proper H κ → ∀ {i j : Fin n}, i < j → κ i = κ j → PartitionH3.PosetLt H i j
@PartitionH3.colorClass_card_le_two : ∀ {n m : ℕ} (H : PartitionH3.NaturalUnitInterval n),
  PartitionH3.HeightTwo H →
    ∀ (κ : Fin n → Fin m), PartitionH3.Proper H κ → ∀ (c : Fin m), (PartitionH3.colorClass κ c).card ≤ 2
@PartitionH3.reverseColors_involutive : ∀ {n m : ℕ} (κ : Fin n → Fin m),
  PartitionH3.reverseColors (PartitionH3.reverseColors κ) = κ
@PartitionH3.proper_reverseColors_iff : ∀ {n m : ℕ} (H : PartitionH3.NaturalUnitInterval n) (κ : Fin n → Fin m),
  PartitionH3.Proper H (PartitionH3.reverseColors κ) ↔ PartitionH3.Proper H κ
@PartitionH3.ascents_reverseColors : ∀ {n m : ℕ} (H : PartitionH3.NaturalUnitInterval n) (κ : Fin n → Fin m),
  PartitionH3.ascents H (PartitionH3.reverseColors κ) = PartitionH3.descents H κ
@PartitionH3.descents_reverseColors : ∀ {n m : ℕ} (H : PartitionH3.NaturalUnitInterval n) (κ : Fin n → Fin m),
  PartitionH3.descents H (PartitionH3.reverseColors κ) = PartitionH3.ascents H κ
@PartitionH3.descents_eq_colorRowInversions : ∀ {n m : ℕ} (H : PartitionH3.NaturalUnitInterval n) (κ : Fin n → Fin m),
