@PartitionH3.alternant_eq_sum : ∀ {m : ℕ} (gamma : Fin m → ℕ),
  PartitionH3.alternant gamma = ∑ sigma, PartitionH3.signCoeff sigma * ∏ i, MvPolynomial.X (sigma i) ^ gamma i
@PartitionH3.powerMonomial_mul_elementary : ∀ {m : ℕ} (gamma : Fin m → ℕ) (b : ℕ),
  PartitionH3.powerMonomial gamma * PartitionH3.elementary m b =
