@PartitionH3.alternant_mul_elementary : ∀ {m : ℕ} (gamma : Fin m → ℕ) (b : ℕ),
  PartitionH3.alternant gamma * PartitionH3.elementary m b =
    ∑ T ∈ Finset.powersetCard b Finset.univ, PartitionH3.alternant (PartitionH3.bump gamma T)
@PartitionH3.alternant_eq_zero_of_eq : ∀ {m : ℕ} (gamma : Fin m → ℕ) (p q : Fin m),
  p ≠ q → gamma p = gamma q → PartitionH3.alternant gamma = 0
PartitionH3.delta_injective : ∀ (m : ℕ), Function.Injective (PartitionH3.delta m)
@PartitionH3.coeff_signed_delta : ∀ {m : ℕ} (sigma : Equiv.Perm (Fin m)),
  (PartitionH3.signCoeff sigma * (MvPolynomial.rename ⇑sigma) (PartitionH3.powerMonomial (PartitionH3.delta m))).coeff
      (PartitionH3.powerExponent (PartitionH3.delta m)) =
    if sigma = 1 then 1 else 0
PartitionH3.vandermonde_delta_coefficient : ∀ (m : ℕ),
  (PartitionH3.vandermonde m).coeff (PartitionH3.powerExponent (PartitionH3.delta m)) = 1
PartitionH3.vandermonde_ne_zero : ∀ (m : ℕ), PartitionH3.vandermonde m ≠ 0
