@PartitionH3.subsetBits_injective : ∀ {m : ℕ}, Function.Injective PartitionH3.subsetBits
PartitionH3.subsetBits_fromBits : ∀ (m : ℕ) (xs : List Bool),
  xs.length = m → PartitionH3.subsetBits (PartitionH3.fromBits m xs) = xs
@PartitionH3.fromBits_subsetBits : ∀ {m : ℕ} (T : Finset (Fin m)), PartitionH3.fromBits m (PartitionH3.subsetBits T) = T
PartitionH3.twoBlockSubset_card : ∀ (m a b j : ℕ),
  b ≤ a → a + b ≤ m → j ≤ b → (PartitionH3.twoBlockSubset m a b j).card = b
PartitionH3.twoBlockSubset_classification : ∀ (m a b : ℕ),
  b ≤ a →
    a + b ≤ m →
      ∀ (T : Finset (Fin m)),
        T.card = b →
          (AlternantSubsets.NoRise (List.take a (PartitionH3.subsetBits T)) ∧
              AlternantSubsets.NoRise (List.drop a (PartitionH3.subsetBits T)) ↔
            ∃ j,
              (j ≤ b ∧ T = PartitionH3.twoBlockSubset m a b j) ∧
                ∀ (k : ℕ), k ≤ b ∧ T = PartitionH3.twoBlockSubset m a b k → k = j)
